// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    // This test contract itself acts as the caller; c checks
    // Bank(msg.sender).supportsToken(), so we must expose it.
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function testFuzz_property(uint256 attempts) public {
        // keep the domain admissible but wide: 1..4 airdrop attempts
        uint256 n = bound(attempts, 1, 4);

        uint256 successes = 0;
        for (uint256 i = 0; i < n; ++i) {
            bool ok;
            try c.airDrop() { ok = true; } catch { ok = false; }
            if (ok) ++successes;
        }

        // General rule: a caller can receive the airdrop exactly once.
        // Repeated attempts by the same caller must revert (hasNoBalance).
        // Mutant (no hasNoBalance): every attempt succeeds -> successes == n > 1.
        assertTrue(successes == 1 && c.tokenBalance(address(this)) == 20);
    }
}
